// Reading plans. Most are generated by splitting chapters evenly over the
// days; "The Big Story" is a hand-picked tour that follows the lessons.

import { BOOKS, getBook } from './books.ts'
import { parseReference, type Passage } from './references.ts'

export interface Plan {
  id: string
  title: string
  description: string
  days: Passage[][]
}

function chaptersOf(bookIds: string[]): Passage[] {
  return bookIds.flatMap((id) => {
    const b = getBook(id)!
    return Array.from({ length: b.chapters }, (_, i) => ({ book: id, startChapter: i + 1, endChapter: i + 1 }))
  })
}

/** Split chapters evenly over a number of days, merging runs in the same book. */
function spread(chs: Passage[], days: number): Passage[][] {
  const out: Passage[][] = []
  for (let d = 0; d < days; d++) {
    const slice = chs.slice(Math.round((d * chs.length) / days), Math.round(((d + 1) * chs.length) / days))
    const merged: Passage[] = []
    for (const c of slice) {
      const last = merged[merged.length - 1]
      if (last && last.book === c.book && last.endChapter === c.startChapter - 1) last.endChapter = c.startChapter
      else merged.push({ ...c })
    }
    out.push(merged)
  }
  return out
}

const ids = (from: string, to: string) => {
  const all = BOOKS.map((b) => b.id)
  return all.slice(all.indexOf(from), all.indexOf(to) + 1)
}

// The Big Story: one or two key passages a day, in the order of the lessons.
const BIG_STORY_DAYS = [
  'Genesis 1', 'Genesis 2', 'Genesis 3', 'Genesis 6-7', 'Genesis 8-9', 'Genesis 11:1-9; Genesis 12', 'Genesis 15', 'Genesis 22',
  'Genesis 37', 'Genesis 45; Genesis 50:15-21', 'Exodus 1-2', 'Exodus 3', 'Exodus 12', 'Exodus 14', 'Exodus 19-20', 'Exodus 32-33',
  'Joshua 1; Joshua 24:14-28', 'Judges 2', 'Ruth 1-2', '1 Samuel 16-17', '2 Samuel 7', '1 Kings 8:1-30', '1 Kings 12', 'Isaiah 9:1-7; Isaiah 11:1-10',
  'Jeremiah 31:27-40', 'Ezekiel 37', 'Daniel 6', 'Nehemiah 8', 'Isaiah 53', 'Luke 1-2', 'Mark 1', 'Matthew 5-7', 'Luke 15', 'John 3; John 11',
  'Mark 14-15', 'Luke 24', 'Acts 1-2', 'Acts 9-10', 'Romans 5; Romans 8', 'Revelation 21-22',
]

function parseDay(s: string): Passage[] {
  return s.split(';').map((x) => parseReference(x.trim())!).filter(Boolean)
}

export const PLANS: Plan[] = [
  {
    id: 'big-story-40',
    title: 'The Big Story in 40 days',
    description: 'Key chapters from creation to new creation, following the Big Story lessons. About 10 minutes a day.',
    days: BIG_STORY_DAYS.map(parseDay),
  },
  {
    id: 'gospels-30',
    title: 'The Gospels in 30 days',
    description: 'Matthew, Mark, Luke and John: the life of Jesus, about 3 chapters a day.',
    days: spread(chaptersOf(ids('MAT', 'JHN')), 30),
  },
  {
    id: 'nt-90',
    title: 'New Testament in 90 days',
    description: 'All 260 chapters of the New Testament, about 3 chapters a day.',
    days: spread(chaptersOf(ids('MAT', 'REV')), 90),
  },
  {
    id: 'proverbs-31',
    title: 'Proverbs in a month',
    description: 'One chapter of practical wisdom each day.',
    days: spread(chaptersOf(['PRO']), 31),
  },
  {
    id: 'bible-365',
    title: 'The whole Bible in a year',
    description: 'All 1,189 chapters from Genesis to Revelation, 3 to 4 chapters a day.',
    days: spread(chaptersOf(BOOKS.map((b) => b.id)), 365),
  },
]

export const getPlan = (id: string) => PLANS.find((p) => p.id === id)

/** Which day of a plan "today" is, counting the start date as day 1. */
export function todayIndex(startedAt: string, length: number): number {
  const start = new Date(startedAt)
  start.setHours(0, 0, 0, 0)
  const now = new Date()
  now.setHours(0, 0, 0, 0)
  const day = Math.floor((now.getTime() - start.getTime()) / 86_400_000) + 1
  return Math.min(Math.max(day, 1), length)
}
